-- TGDesk: taxonomia planejada de tipos de chamado e campos din?micos.
-- O cliente recebe textos/campos; o servidor mant?m os tipos e v?nculos com servi?os.

ON CONFLICT (key) DO UPDATE SET
    label=excluded.label,
    icon=excluded.icon,
    position=excluded.position,
    active=true,
    updated_at=now();

ON CONFLICT (type_key,field_key) DO UPDATE SET
    label=excluded.label,
    help=excluded.help,
    kind=excluded.kind,
    options=excluded.options,
    required=excluded.required,
    depends_on=excluded.depends_on,
    depends_value=excluded.depends_value,
    position=excluded.position,
    active=true;

UPDATE service_catalog AS service
SET ticket_type_key = mapping.ticket_type_key, updated_at = now()
FROM (VALUES
    ('software_diagnostico_profundo','lentidao_intermitente'),
    ('software_remocao_malware','malware_seguranca'),
    ('software_otimizacao_inicializacao','lentidao_intermitente'),
